// Rearranges `nums` in-place into nondecreasing order.
// Post-state is a permutation of the pre-state (Rust's safe sort only reorders).
pub fn test1(nums: &mut Vec<u32>) {
    // `sort_unstable` is in-place (O(1) extra memory, aside from recursion stack),
    // deterministic, terminates, and results in nondecreasing order.
    // It may reorder equal elements relative to each other, which is allowed here.
    nums.sort_unstable();
}

